void MetalLook::drawRotarySlider(juce::Graphics&g,int x,int y,int w,int h,float value,float start,float end,juce::Slider&){auto r=juce::Rectangle<float>(float(x),float(y),float(w),float(h)).reduced(9);float d=std::min(r.getWidth(),r.getHeight());r=juce::Rectangle<float>(d,d).withCentre(r.getCentre());auto c=r.getCentre();g.setColour(juce::Colours::black.withAlpha(.3f));g.fillEllipse(r.translated(1,4));g.setGradientFill(juce::ColourGradient(juce::Colour(0xfffafaf6),r.getX(),r.getY(),juce::Colour(0xff777b7a),r.getRight(),r.getBottom(),false));g.fillEllipse(r);g.setColour(juce::Colour(0xff4a4e4e));g.drawEllipse(r,1.2f);g.setColour(juce::Colour(0xffc2c7c5));g.drawEllipse(r.reduced(5),1);float a=start+value*(end-start);g.setColour(juce::Colour(0xff292d2d));g.drawLine(c.x+std::sin(a)*d*.1f,c.y-std::cos(a)*d*.1f,c.x+std::sin(a)*d*.38f,c.y-std::cos(a)*d*.38f,3);for(int i=0;i<=10;++i){float t=start+(end-start)*i/10;g.drawLine(c.x+std::sin(t)*(d*.5f+3),c.y-std::cos(t)*(d*.5f+3),c.x+std::sin(t)*(d*.5f+6),c.y-std::cos(t)*(d*.5f+6),1);}}
void StepGrid::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff171c1c));float cw=getWidth()/16.f;int h=getHeight();for(int i=0;i<16;++i){int n=page*16+i;bool active=p.get(sid(n,"active"))>.5;bool lit=p.currentStep==n;auto x=int(i*cw);g.setColour(lit?juce::Colour(0xffb83a27):juce::Colour(0xff303737));g.fillRoundedRectangle(float(x+2),4,cw-4,23,3);g.setColour(juce::Colours::whitesmoke);g.setFont(12);g.drawText(juce::String(n+1),x,4,int(cw),22,juce::Justification::centred);int note=int(p.get(sid(n,"note")));g.setColour(active?juce::Colour(0xffe96343):juce::Colour(0xff666d6c));g.drawText(juce::MidiMessage::getMidiNoteName(note,true,true,3),x,31,int(cw),22,juce::Justification::centred);g.setColour(juce::Colour(0xff384040));g.drawVerticalLine(x,29,float(h));for(int row=0;row<3;++row){const char*key=row==0?"active":row==1?"accent":"slide";bool on=p.get(sid(n,key))>.5;g.setColour(on?juce::Colour(row==0?0xffb74936:0xffe55c3c):juce::Colour(0xff424948));g.fillRoundedRectangle(float(x+9),float(63+row*28),cw-18,16,2);g.setColour(on?juce::Colours::white:juce::Colour(0xff858c89));g.setFont(9);g.drawText(row==0?"GATE":row==1?"ACC":"SLIDE",x,62+row*28,int(cw),18,juce::Justification::centred);}
 g.setColour(juce::Colour(0xffa6b1a9));int gh=int(p.get(sid(n,"gate"))*40);g.fillRect(x+int(cw)/2-3,h-14-gh,6,gh);if(n==selected){g.setColour(juce::Colour(0xfff2dcb1));g.drawRect(x+1,1,int(cw)-2,h-2,1);}}}
void StepGrid::mouseDown(const juce::MouseEvent&e){int col=std::clamp(int(e.position.x/(getWidth()/16.f)),0,15);selected=page*16+col;int row=int((e.position.y-62)/28);if(e.position.y>=62&&e.position.y<146&&row>=0&&row<3){auto id=sid(selected,row==0?"active":row==1?"accent":"slide");p.undo.beginNewTransaction();p.set(id,p.get(id)>.5?0.f:1.f);}if(selection)selection(selected);repaint();}
void StepGrid::mouseWheelMove(const juce::MouseEvent&e,const juce::MouseWheelDetails&w){int col=std::clamp(int(e.position.x/(getWidth()/16.f)),0,15);selected=page*16+col;p.set(sid(selected,"note"),p.get(sid(selected,"note"))+(w.deltaY>0?1.f:-1.f)*(e.mods.isShiftDown()?12.f:1.f));if(selection)selection(selected);repaint();}
