void Editor::userFile(bool saving){chooser=std::make_unique<juce::FileChooser>(saving?"Save Psy303 preset":"Load Psy303 preset",juce::File{},"*.psy303");auto safe=juce::Component::SafePointer<Editor>(this);chooser->launchAsync(saving?(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting):(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles),[safe,saving](const juce::FileChooser&c){if(!safe)return;auto f=c.getResult();if(f==juce::File{})return;try{if(saving){safe->lastFile=f.withFileExtension("psy303");safe->p.saveUser(safe->lastFile);}else {safe->p.loadUser(f);safe->lastFile=f;}safe->status.setText(saving?"Preset saved.":"Preset loaded.",juce::dontSendNotification);}catch(const std::exception&e){safe->status.setText(e.what(),juce::dontSendNotification);}});}
void Editor::exportFile(){if(busy)return;int type=exportType.getSelectedItemIndex();chooser=std::make_unique<juce::FileChooser>("Export pattern / kick",juce::File{},type==0?"*.mid":"*.wav");auto safe=juce::Component::SafePointer<Editor>(this);chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[safe,type](const juce::FileChooser&c){if(!safe)return;auto f=c.getResult();if(f==juce::File{})return;auto*e=safe.getComponent();if(e->worker.joinable())e->worker.join();auto preset=e->p.snapshot();int count=int(e->repeats.getValue()),kick=e->kickSelect.getSelectedItemIndex();bool withTail=e->tail.getToggleState();double bpm=e->tempo.getValue();KickParams kp{e->p.get("kTune"),e->p.get("kStart"),e->p.get("kPitch"),e->p.get("kDecay"),e->p.get("kClick"),e->p.get("kDrive"),e->p.get("kLevel")};auto path=std::filesystem::u8path(f.withFileExtension(type==0?"mid":"wav").getFullPathName().toStdString());e->busy=true;e->exportButton.setEnabled(false);e->status.setText("Rendering...",juce::dontSendNotification);e->worker=std::thread([e,preset,count,kick,kp,withTail,bpm,path,type]{try{if(type==0)midi(path,preset.pattern,bpm);else if(type==13){Kick k;k.p=kp;k.trigger();std::vector<float> a(96000);for(auto&x:a)x=k.tick(48000);wav(path,a,48000);}else{int index=type-1;int sr=index/4==0?44100:index/4==1?48000:96000;auto a=render(preset,sr,count,bpm,withTail);wav(path,a,sr,index%4>=2?32:24,index%2==1?2:1);}e->result=1;}catch(...){e->result=-1;}e->busy=false;});});}
